/bin/bash -c "node --input-type=module <<'EOF'
import { performance } from 'node:perf_hooks'
import { createInventory } from './src/report.mjs'

const items = createInventory()

function current() {
  const seen = []
  const report = []
  for (const item of items) {
    const key = "'`${item.productId}:${item.region}`
    if (seen.includes(key)) continue
    seen.push(key)
    const regionalItems = items.filter((candidate) => candidate.region === item.region)
    const regionalUnits = regionalItems.reduce((sum, candidate) => sum + candidate.units, 0)
    report.push({ productId: item.productId, region: item.region, units: item.units, share: regionalUnits === 0 ? 0 : item.units / regionalUnits })
  }
  return report.sort((left, right) => right.share - left.share || left.productId.localeCompare(right.productId) || left.region.localeCompare(right.region))
}

function setOnly() {
  const seen = new Set()
  const report = []
  for (const item of items) {
    const key = `${item.productId}:${item.region}`
    if (seen.has(key)) continue
    seen.add(key)
    const regionalItems = items.filter((candidate) => candidate.region === item.region)
    const regionalUnits = regionalItems.reduce((sum, candidate) => sum + candidate.units, 0)
    report.push({ productId: item.productId, region: item.region, units: item.units, share: regionalUnits === 0 ? 0 : item.units / regionalUnits })
  }
  return report.sort((left, right) => right.share - left.share || left.productId.localeCompare(right.productId) || left.region.localeCompare(right.region))
}

function totalsOnly() {
  const seen = []
  const report = []
  const totals = new Map()
  for (const candidate of items) totals.set(candidate.region, (totals.get(candidate.region) ?? 0) + candidate.units)
  for (const item of items) {
    const key = `${item.productId}:${item.region}`
    if (seen.includes(key)) continue
    seen.push(key)
    const regionalUnits = totals.get(item.region)
    report.push({ productId: item.productId, region: item.region, units: item.units, share: regionalUnits === 0 ? 0 : item.units / regionalUnits })
  }
  return report.sort((left, right) => right.share - left.share || left.productId.localeCompare(right.productId) || left.region.localeCompare(right.region))
}

function both() {
  const seen = new Set()
  const report = []
  const totals = new Map()
  for (const candidate of items) totals.set(candidate.region, (totals.get(candidate.region) ?? 0) + candidate.units)
  for (const item of items) {
    const key = `${item.productId}:${item.region}`
    if (seen.has(key)) continue
    seen.add(key)
    const regionalUnits = totals.get(item.region)
    report.push({ productId: item.productId, region: item.region, units: item.units, share: regionalUnits === 0 ? 0 : item.units / regionalUnits })
  }
  return report.sort((left, right) => right.share - left.share || left.productId.localeCompare(right.productId) || left.region.localeCompare(right.region))
}

const variants = { current, setOnly, totalsOnly, both }
const samples = Object.fromEntries(Object.keys(variants).map((name) => [name, []]))
for (const fn of Object.values(variants)) fn()
for (let round = 0; round < 7; round += 1) {
  for (const [name, fn] of Object.entries(variants)) {
    const start = performance.now()
    fn()
    samples[name].push(Number((performance.now() - start).toFixed(3)))
  }
}
for (const [name, values] of Object.entries(samples)) {
  const sorted = [...values].sort((a, b) => a - b)
  console.log(JSON.stringify({ name, samplesMs: values, medianMs: sorted[Math.floor(sorted.length / 2)] }))
}
EOF'

