/bin/bash -c "node --input-type=module <<'EOF'
import { createHash } from 'node:crypto'
import { startReportServer } from './server.mjs'
const { server, url } = await startReportServer()
try {
  const response = await fetch("'`${url}/report`)
  const body = Buffer.from(await response.arrayBuffer())
  console.log(JSON.stringify({ status: response.status, contentType: response.headers.get('"'content-type'), bytes: body.length, sha256: createHash('sha256').update(body).digest('hex') }))
} finally {
  await new Promise((resolve) => server.close(resolve))
}
EOF"

